-- ResQGrid seed data for India (generated by scripts/make_seed.py). Run after schema.sql.

on conflict (id) do update set name = excluded.name, state = excluded.state, river = excluded.river, dist_river_km = excluded.dist_river_km, slope_deg = excluded.slope_deg, flood_prone = excluded.flood_prone, relief_m = excluded.relief_m, population = excluded.population, centroid = excluded.centroid, boundary = excluded.boundary;

on conflict (id) do nothing;

